update.foreach:
UPDATE SYSTEM_COLLABORATION_TEST.md_file_storage
SET upload_status = #{item.uploadStatus},
    update_by = #{item.updateBy},
    update_time = #{item.updateTime}
WHERE id = #{item.id}

mapper.select:
SELECT DISTINCT s.id, s.business_type, s.business_id, s.storage_provider, s.bucket_name, s.object_name, s.original_file_name, s.file_ext, s.content_type, s.file_size, s.etag, s.upload_status, s.upload_user_id, s.upload_user_name, s.completed_time, s.remark, s.create_by, s.create_time, s.update_by, s.update_time FROM SYSTEM_COLLABORATION_TEST.md_file_storage s LEFT JOIN SYSTEM_COLLABORATION_TEST.md_data_relation d ON d.storage_file_id = s.id WHERE s.business_type = #{businessType} AND s.bucket_name = #{bucketName} AND s.original_file_name IN
#{fileName}
AND (d.experiment_id = #{experimentId} OR s.business_id IS NULL OR s.business_id = '')
AND s.upload_user_id = #{uploadUserId}
AND s.create_by = #{createBy}
AND s.create_time >= #{createTime}
